const sqlite3 = require('sqlite3').verbose();

const oggi = new Date(new Date().toLocaleString('en-US', { timeZone: 'Europe/Rome' }));
const oggiStr = `${oggi.getFullYear()}-${String(oggi.getMonth()+1).padStart(2,'0')}-${String(oggi.getDate()).padStart(2,'0')}`;

const tasks = await new Promise((resolve, reject) => {
  const db = new sqlite3.Database('/data/segretario.db');
  db.all(
    `SELECT descrizione, scadenza, priorita, reminder_count 
     FROM task 
     WHERE stato = 'aperto'
     AND (scadenza IS NULL OR date(scadenza) <= ?)
     ORDER BY priorita DESC, scadenza ASC
     LIMIT 20`,
    [oggiStr],
    function(err, rows) {
      db.close();
      if (err) reject(err);
      else resolve(rows);
    }
  );
});

const taskFormattati = tasks.map(t => {
  const scad = t.scadenza ? ` (scadenza: ${t.scadenza.slice(0,10)})` : ' (nessuna scadenza)';
  const arretrato = t.reminder_count > 0 ? ` [${t.reminder_count} solleciti]` : '';
  return `- ${t.descrizione}${scad} [${t.priorita}]${arretrato}`;
}).join('\n');

return [{
  json: {
    data_oggi: oggiStr,
    task_aperti: taskFormattati || 'Nessun task in scadenza oggi.',
    task_count: tasks.length
  }
}];

const outlookData = $input.first().json;
const eventi = [];

if (outlookData.value && Array.isArray(outlookData.value)) {
  for (const ev of outlookData.value) {
    const inizio = ev.start?.dateTime ? 
      new Date(ev.start.dateTime).toLocaleTimeString('it-IT', {hour:'2-digit', minute:'2-digit', timeZone:'Europe/Rome'}) : '';
    eventi.push(`- ${inizio} ${ev.subject || 'Senza titolo'} [Outlook]`);
  }
}

return [{
  json: {
    eventi_outlook: eventi.join('\n') || '',
    data_oggi: $('Leggi task oggi').item.json.data_oggi,
    task_aperti: $('Leggi task oggi').item.json.task_aperti,
    task_count: $('Leggi task oggi').item.json.task_count
  }
}];

// Dati Outlook dal nodo intermedio
const eventiOutlook = $('Salva risultati Outlook Briefing').item.json.eventi_outlook || '';
const dataOggi = $('Salva risultati Outlook Briefing').item.json.data_oggi;
const taskAperti = $('Salva risultati Outlook Briefing').item.json.task_aperti;
const taskCount = $('Salva risultati Outlook Briefing').item.json.task_count;

// Dati Google dall'input corrente (in serie dopo Salva risultati Outlook Briefing)
const eventiGoogle = [];
const items = $input.all();

for (const item of items) {
  const data = item.json;
  if (data.id && data.summary !== undefined) {
    const dataEvento = data.start?.dateTime?.slice(0,10) || data.start?.date?.slice(0,10) || '';
    if (dataEvento === dataOggi) {
      const inizio = data.start?.dateTime ?
        DateTime.fromISO(data.start.dateTime).setZone('Europe/Rome').toFormat('HH:mm') : '';
      eventiGoogle.push(`- ${inizio} ${data.summary || 'Senza titolo'} [Google]`);
    }
  }
}

const tuttiEventi = [eventiOutlook, ...eventiGoogle].filter(e => e).join('\n');

const oggi = new Date(new Date().toLocaleString('en-US', { timeZone: 'Europe/Rome' }));
const giorni = ['domenica','lunedì','martedì','mercoledì','giovedì','venerdì','sabato'];
const mesi = ['gennaio','febbraio','marzo','aprile','maggio','giugno','luglio','agosto','settembre','ottobre','novembre','dicembre'];
const nomeGiorno = giorni[oggi.getDay()];
const dataFormattata = `${nomeGiorno} ${oggi.getDate()} ${mesi[oggi.getMonth()]} ${oggi.getFullYear()}`;

const testo = `Buongiorno Cesare! 🌅 Oggi è ${dataFormattata}.

📅 APPUNTAMENTI DI OGGI:
${tuttiEventi || 'Nessun appuntamento oggi.'}

✅ TASK IN SCADENZA:
${taskAperti}

${taskCount > 0 ? `Hai ${taskCount} task aperti da completare oggi. Buona giornata!` : 'Nessun task in scadenza oggi. Buona giornata!'}`;

return [{
  json: {
    testo_risposta: testo
  }
}];

const http = require('http');

const testo = $input.first().json.testo_risposta;
const destinatario = '+393495931632'; // sostituisci con il tuo numero personale

const payload = JSON.stringify({
  message: testo,
  number: '+393517872627',
  recipients: [destinatario]
});

await new Promise((resolve, reject) => {
  const options = {
    hostname: 'segretario_signal_cli',
    port: 8080,
    path: '/v2/send',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(payload)
    }
  };

  const req = http.request(options, (res) => {
    let data = '';
    res.on('data', chunk => data += chunk);
    res.on('end', () => {
      if (res.statusCode === 200 || res.statusCode === 201) {
        resolve(data);
      } else {
        reject(new Error(`Status ${res.statusCode}: ${data}`));
      }
    });
  });

  req.on('error', reject);
  req.write(payload);
  req.end();
});

return [{
  json: {
    stato: 'briefing inviato',
    data: $('Salva risultati Outlook Briefing').item.json.data_oggi
  }
}];
